{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Pub/Sub topic lacks customer-managed encryption",
      "resource": "google_pubsub_topic.notification_queue",
      "severity": "MEDIUM",
      "explanation": "The production notification topic does not specify a KMS key, so messages are encrypted only with Google-managed keys. A customer-managed key provides greater control over key rotation, access, and revocation."
    }
  ],
  "patched_code": "variable "pubsub_kms_key_name" {
  description = "Fully qualified Cloud KMS CryptoKey name used to encrypt the Pub/Sub topic."
  type        = string
}

resource "google_pubsub_topic" "notification_queue" {
  name         = "insurance-claims-processing-platform-pubsub-notifications"
  kms_key_name = var.pubsub_kms_key_name

  labels = {
    environment = "production"
    component   = "notifications"
  }
}
",
  "fix_summary": "Configured the Pub/Sub topic to use a caller-supplied customer-managed Cloud KMS key. Added a required variable for the existing key's fully qualified name without embedding credentials or inventing a key resource."
}
